// agingPill 帳齡分桶的膠囊樣式。
func agingPill(bucket string) string {
	switch bucket {
	case "0-30":
		return "p-completed"
	case "31-60":
		return "p-apprpend"
	case "61-90":
		return "p-waitparts"
	default:
		return "p-apprno"
	}
}

